   <head>
     <meta charset="UTF-8" />
     <meta name="viewport" content="width=device-width, initial-scale=1.0" />
     <title>Image Preview</title>
     <style>
       :root {
         color-scheme: light;
         --bg: #f4f7fb;
         --surface: rgba(255, 255, 255, 0.86);
         --surface-strong: #ffffff;
         --text: #132238;
         --muted: #5c6b80;
         --border: rgba(19, 34, 56, 0.12);
         --shadow: 0 24px 60px rgba(19, 34, 56, 0.14);
         --primary: #2563eb;
         --danger: #dc2626;
         --danger-strong: #b91c1c;
         --radius-xl: 28px;
         --radius-lg: 20px;
         --radius-md: 14px;
       }

       * {
         box-sizing: border-box;
       }

       body {
         margin: 0;
         min-height: 100vh;
         font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
         color: var(--text);
         background:
           radial-gradient(circle at top left, rgba(37, 99, 235, 0.16), transparent 35%),
           radial-gradient(circle at bottom right, rgba(14, 165, 233, 0.18), transparent 28%),
           var(--bg);
       }

       button {
         font: inherit;
       }

       .page {
         min-height: 100vh;
         display: grid;
         place-items: center;
         padding: 32px;
       }

       .shell {
         width: min(960px, 100%);
         display: grid;
         grid-template-columns: 1.2fr 0.8fr;
         gap: 28px;
         align-items: center;
       }

       .hero,
       .panel {
         border: 1px solid var(--border);
         background: var(--surface);
         backdrop-filter: blur(18px);
         box-shadow: var(--shadow);
       }

       .hero {
         border-radius: var(--radius-xl);
         padding: 28px;
       }

       .eyebrow {
         display: inline-flex;
         align-items: center;
         gap: 8px;
         padding: 8px 12px;
         border-radius: 999px;
         background: rgba(37, 99, 235, 0.08);
         color: var(--primary);
         font-weight: 600;
         font-size: 0.9rem;
       }

       .hero h1 {
         margin: 18px 0 10px;
         font-size: clamp(2rem, 4vw, 3.4rem);
         line-height: 1.02;
         letter-spacing: -0.05em;
       }

       .hero p {
         margin: 0;
         max-width: 54ch;
         color: var(--muted);
         font-size: 1.02rem;
         line-height: 1.6;
       }

       .panel {
         border-radius: var(--radius-xl);
         padding: 18px;
       }

       .preview {
         overflow: hidden;
         border-radius: var(--radius-lg);
         background: #0f172a;
       }

       .preview img {
         display: block;
         width: 100%;
         aspect-ratio: 4 / 3;
         object-fit: cover;
       }

       .meta {
         padding: 18px 8px 4px;
       }

       .meta h2 {
         margin: 0 0 8px;
         font-size: 1.1rem;
       }

       .meta p {
         margin: 0;
         color: var(--muted);
         line-height: 1.5;
       }

       .actions {
         display: flex;
         gap: 12px;
         padding: 18px 8px 4px;
       }

       .button {
         border: 0;
         border-radius: 999px;
         padding: 12px 18px;
         font-weight: 600;
         cursor: pointer;
         transition: transform 140ms ease, box-shadow 140ms ease, background-color 140ms ease;
       }

       .button:hover {
         transform: translateY(-1px);
       }

       .button.primary {
         background: var(--primary);
         color: white;
         box-shadow: 0 12px 24px rgba(37, 99, 235, 0.24);
       }

       .button.ghost {
         background: rgba(19, 34, 56, 0.06);
         color: var(--text);
       }

       .dialog-backdrop {
         position: fixed;
         inset: 0;
         display: grid;
         place-items: center;
         padding: 24px;
         background: rgba(8, 15, 29, 0.56);
         opacity: 0;
         pointer-events: none;
         transition: opacity 160ms ease;
       }

       .dialog-backdrop.open {
         opacity: 1;
         pointer-events: auto;
       }

       .dialog {
         width: min(100%, 460px);
         border: 1px solid rgba(255, 255, 255, 0.18);
         border-radius: 24px;
         background: var(--surface-strong);
         box-shadow: 0 32px 80px rgba(2, 6, 23, 0.32);
         overflow: hidden;
         transform: translateY(8px) scale(0.98);
         transition: transform 160ms ease;
       }

       .dialog-backdrop.open .dialog {
         transform: translateY(0) scale(1);
       }

       .dialog-header,
       .dialog-body,
       .dialog-footer {
         padding: 22px;
       }

       .dialog-header {
         display: flex;
         align-items: center;
         justify-content: space-between;
         border-bottom: 1px solid var(--border);
       }

       .dialog-title {
         margin: 0;
         font-size: 1.15rem;
       }

       .close {
         width: 40px;
         height: 40px;
         border: 0;
         border-radius: 999px;
         background: rgba(19, 34, 56, 0.06);
         color: var(--muted);
         cursor: pointer;
       }

       .dialog-body p {
         margin: 0;
         color: var(--muted);
         line-height: 1.6;
       }

       .dialog-footer {
         display: flex;
         justify-content: flex-end;
         gap: 12px;
         border-top: 1px solid var(--border);
         background: rgba(245, 247, 250, 0.7);
       }

       .button.danger {
         background: var(--danger);
         color: white;
       }

       .button.danger:hover {
         background: var(--danger-strong);
       }

       @media (max-width: 840px) {
         .shell {
           grid-template-columns: 1fr;
         }
       }
     </style>
   </head>
   <body>
     <div id="app"></div>

     <script>
       const imageSrc =
         'data:image/svg+xml;charset=UTF-8,' +
         encodeURIComponent(`
           <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 1200 900">
             <defs>
               <linearGradient id="g" x1="0" x2="1" y1="0" y2="1">
                 <stop offset="0%" stop-color="#2563eb"/>
                 <stop offset="100%" stop-color="#0f172a"/>
               </linearGradient>
             </defs>
             <rect width="1200" height="900" fill="url(#g)"/>
             <circle cx="860" cy="250" r="190" fill="rgba(255,255,255,0.14)"/>
             <circle cx="300" cy="650" r="240" fill="rgba(255,255,255,0.08)"/>
             <rect x="180" y="180" width="540" height="420" rx="36" fill="rgba(255,255,255,0.12)"/>
             <path d="M260 520L430 360l120 126 84-84 166 198H260z" fill="rgba(255,255,255,0.86)"/>
             <circle cx="404" cy="300" r="42" fill="rgba(255,255,255,0.86)"/>
           </svg>
         `);

       const state = {
         isDialogOpen: false,
       };

       function App() {
         return `
           <main class="page">
             <section class="shell" aria-label="Image preview page">
               ${Hero()}
               ${ImagePanel()}
             </section>
           </main>
           ${ConfirmDialog()}
         `;
       }

       function Hero() {
         return `
           <div class="hero">
             <span class="eyebrow">Library preview</span>
             <h1>Review the image before you remove it.</h1>
             <p>
               Keep your library organized with a focused preview surface and a clear delete confirmation.
             </p>
           </div>
         `;
       }

       function ImagePanel() {
         return `
           <article class="panel">
             <div class="preview">
               <img src="${imageSrc}" alt="Abstract library image preview" />
             </div>
             <div class="meta">
               <h2>Sunset editorial concept</h2>
               <p>Uploaded today · 4.2 MB · 4000 × 3000 px</p>
             </div>
             <div class="actions">
               <button class="button ghost" type="button">Edit</button>
               <button class="button primary trigger" type="button" data-open-dialog>
                 Delete image
               </button>
             </div>
           </article>
         `;
       }

       function ConfirmDialog() {
         return `
           <div
             class="dialog-backdrop${state.isDialogOpen ? ' open' : ''}"
             data-backdrop
             aria-hidden="${state.isDialogOpen ? 'false' : 'true'}"
           >
             <section
               class="dialog"
               role="dialog"
               aria-modal="true"
               aria-labelledby="delete-title"
               aria-describedby="delete-description"
             >
               <header class="dialog-header">
                 <h2 class="dialog-title" id="delete-title">Delete this image?</h2>
                 <button class="close" type="button" aria-label="Close dialog" data-close-dialog>
                   &times;
                 </button>
               </header>
               <div class="dialog-body">
                 <p id="delete-description">
                   This will permanently remove the image from your library. You can’t undo this action.
                 </p>
               </div>
               <footer class="dialog-footer">
                 <button class="button ghost" type="button" data-close-dialog>Cancel</button>
                 <button class="button danger" type="button">Delete</button>
               </footer>
             </section>
           </div>
         `;
       }

       function render() {
         document.getElementById('app').innerHTML = App();
       }

       function openDialog() {
         state.isDialogOpen = true;
         render();
         bindEvents();
       }

       function closeDialog() {
         state.isDialogOpen = false;
         render();
         bindEvents();
       }

       function bindEvents() {
         document.querySelectorAll('[data-open-dialog]').forEach((button) => {
           button.addEventListener('click', openDialog);
         });

         document.querySelectorAll('[data-close-dialog]').forEach((button) => {
           button.addEventListener('click', closeDialog);
         });

         const backdrop = document.querySelector('[data-backdrop]');
         if (backdrop) {
           backdrop.addEventListener('click', (event) => {
             if (event.target === backdrop) closeDialog();
           });
         }
       }

       document.addEventListener('keydown', (event) => {
         if (event.key === 'Escape' && state.isDialogOpen) closeDialog();
       });

       render();
       bindEvents();
     </script>
   </body>
 </html>

')
